Here is a comprehensive pytest suite covering happy paths, edge cases, and error cases.

```python
import pytest


def group_by(items: list, key_fn) -> dict:
    result = {}
    for item in items:
        k = key_fn(item)
        result.setdefault(k, []).append(item)
    return result


# -----------------------------------------------------------------------------
# Happy path
# -----------------------------------------------------------------------------

def test_group_by_even_odd():
    items = [1, 2, 3, 4, 5, 6]
    result = group_by(items, lambda x: x % 2)
    assert result == {0: [2, 4, 6], 1: [1, 3, 5]}


def test_group_by_string_length():
    items = ["a", "bb", "c", "dd", "eee"]
    result = group_by(items, len)
    assert result == {1: ["a", "c"], 2: ["bb", "dd"], 3: ["eee"]}


def test_group_by_tuple_items():
    items = [("apple", "fruit"), ("carrot", "veg"), ("banana", "fruit")]
    result = group_by(items, lambda x: x[1])
    assert result == {
        "fruit": [("apple", "fruit"), ("banana", "fruit")],
        "veg": [("carrot", "veg")],
    }


# -----------------------------------------------------------------------------
# Edge cases
# -----------------------------------------------------------------------------

def test_empty_list():
    assert group_by([], lambda x: x) == {}


def test_single_item():
    assert group_by([42], lambda x: x) == {42: [42]}


def test_all_items_same_key():
    items = [1, 2, 3]
    result = group_by(items, lambda x: "same")
    assert result == {"same": [1, 2, 3]}


def test_all_items_unique_keys():
    items = [1, 2, 3]
    result = group_by(items, lambda x: x)
    assert result == {1: [1], 2: [2], 3: [3]}


def test_preserves_insertion_order():
    """Keys and their grouped items should appear in first-seen order."""
    items = [3, 1, 2, 1, 3, 2]
    result = group_by(items, lambda x: x)
    assert list(result.keys()) == [3, 1, 2]
    assert result[3] == [3, 3]
    assert result[1] == [1, 1]
    assert result[2] == [2, 2]


def test_none_is_a_valid_key():
    """None is hashable and can be used as a dict key."""
    items = [1, 2, 3]
    result = group_by(items, lambda x: None)
    assert result == {None: [1, 2, 3]}


def test_mixed_key_types():
    """Python allows mixed but hashable key types (e.g., int and str)."""
    items = [1, "1", 2, "2"]
    result = group_by(items, lambda x: x)
    assert result == {1: [1], "1": ["1"], 2: [2], "2": ["2"]}


# -----------------------------------------------------------------------------
# Error cases
# -----------------------------------------------------------------------------

def test_items_none_raises_type_error():
    with pytest.raises(TypeError):
        group_by(None, lambda x: x)


def test_key_fn_none_raises_type_error():
    with pytest.raises(TypeError):
        group_by([1, 2, 3], None)


def test_key_fn_exception_propagates():
    def bad_key(x):
        if x == "boom":
            raise ValueError("intentional error")
        return x

    with pytest.raises(ValueError, match="intentional error"):
        group_by(["a", "boom", "c"], bad_key)


def test_unhashable_key_raises_type_error():
    """setdefault requires the key to be hashable."""
    with pytest.raises(TypeError):
        group_by([1, 2], lambda x: [x])  # list is unhashable
